<?php require __DIR__.'/../lib/bootstrap.php';$key=$_SERVER['HTTP_X_API_KEY']??'';if(!$CONFIG['api_key']||!hash_equals($CONFIG['api_key'],$key))json_out(['error'=>'Unauthorized'],401);$in=json_decode(file_get_contents('php://input'),true)?:[];$to=trim($in['to']??'');$iccid=trim($in['iccid']??$CONFIG['iccid']);$body=trim($in['message']??'');if(!$body||(!$to&&!$iccid))json_out(['error'=>'to and message required'],422);if($to&&!preg_match('/^\+[1-9][0-9]{7,14}$/',$to))json_out(['error'=>'invalid phone number'],422);try{if($to){$id=add_row('messages',['to'=>$to,'body'=>$body,'status'=>'queued','created_at'=>date('c'),'updated_at'=>date('c')]);json_out(['success'=>true,'id'=>$id,'status'=>'queued']);}$r=send_sms($iccid,$body);$id=add_row('messages',['iccid'=>$iccid,'body'=>$body,'status'=>'sent','response'=>$r,'created_at'=>date('c')]);json_out(['success'=>true,'id'=>$id,'provider'=>$r]);}catch(Throwable $e){json_out(['success'=>false,'error'=>$e->getMessage()],502);}